<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alamat</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h4 mb-3">Alamat Pengiriman</h1>
<div class="row g-3"><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body"><?php foreach ($addresses as $address): ?><div class="border-bottom py-2"><strong><?php echo html_escape($address->label); ?><?php if ($address->is_primary): ?> <span class="badge text-bg-success">Utama</span><?php endif; ?></strong><div><?php echo html_escape($address->recipient_name . ' - ' . $address->phone); ?></div><div class="text-muted"><?php echo html_escape($address->address_line . ', ' . $address->city); ?></div></div><?php endforeach; ?><?php if (!$addresses): ?><div class="text-muted">Belum ada alamat.</div><?php endif; ?></div></div></div>
<div class="col-lg-5"><div class="card border-0 shadow-sm"><div class="card-body"><form method="post" action="<?php echo site_url('customer/addresses/store'); ?>"><input type="hidden" name="<?php echo $this->security->get_csrf_token_name(); ?>" value="<?php echo $this->security->get_csrf_hash(); ?>"><div class="mb-2"><input class="form-control" name="label" placeholder="Label (Rumah/Kantor)" required></div><div class="mb-2"><input class="form-control" name="recipient_name" placeholder="Nama penerima" required></div><div class="mb-2"><input class="form-control" name="phone" placeholder="Nomor telepon" required></div><div class="mb-2"><textarea class="form-control" name="address_line" placeholder="Alamat lengkap" required></textarea></div><div class="mb-2"><input class="form-control" name="district" placeholder="Kecamatan"></div><div class="mb-2"><input class="form-control" name="city" placeholder="Kota" required></div><div class="mb-2"><input class="form-control" name="province" placeholder="Provinsi" required></div><div class="mb-2"><input class="form-control" name="postal_code" placeholder="Kode pos"></div><div class="form-check mb-3"><input class="form-check-input" name="is_primary" type="checkbox" value="1" id="primary"><label class="form-check-label" for="primary">Alamat utama</label></div><button class="btn btn-success w-100" type="submit">Simpan Alamat</button></form></div></div></div></div></main></body></html>
